                new RuntimeDefinitionIdEntry(new RuntimeDefinitionId(420, 122), false),
                new RuntimeDefinitionIdEntry(new RuntimeDefinitionId(421, 1), false),
                new RuntimeDefinitionIdEntry(new RuntimeDefinitionId(421, 2), false),
            });

        internal static bool IsActive(int domainId, int value) => value > 0 && Catalog.IsActive(new RuntimeDefinitionId(domainId, value));
    }
}
